/**
 * Asset Manifest — Lists every sprite texture in the game.
 * Isometric tiles and towers are loaded from PNGs in BootScene.
 * Procedural sprites are generated by SpriteGenerator.
 */

export interface AssetEntry {
  key: string;
  width: number;
  height: number;
  category: string;
  description: string;
}

